function UIBattlingDiscoverCardRoleCell:InitCellInfo(roleId, posData, star, para)
    local characterBattleData = UIBattlingDataMgr:GetCharactorDataById(roleId)
    local cardId = characterBattleData.cardId -- 角色卡牌Id
    local cardVo = CardConfMgr:GetCardByRefId(cardId)
    local roleName = cardVo.name -- 人物角色姓名
    self.TxtCharactorName.text = checkString(roleName)
    self:InitRoleSkill(characterBattleData, posData, star, para)
end

function UIBattlingDiscoverCardRoleCell:InitRoleSkill(roleData, posData, star, para)
    local listRoleSkill = {}
    table.insert(listRoleSkill, roleData.skillList["1"].skillId)
    table.insert(listRoleSkill, roleData.skillList["2"].skillId)
    if isNull(self.listSkillCell) then self.listSkillCell = {} end
    -- print("->listRoleSkill", table.dump(listRoleSkill))
    for i, skill in pairs(listRoleSkill) do
        local go = KTool.Instantiate(self.controller.gameObject, self.SkillCardCell.gameObject)
        if not IsNull(go) then
            local lbSkillCard = KTool.GetComponent(go, typeof(LuaBehaviour))
            if not IsNull(lbSkillCard) then
                lbSkillCard:Init()
                local ltSkillCard = lbSkillCard.Env
                if ltSkillCard then
                    ltSkillCard:SetSkillCardInfo(checkInt(skill), roleData.id, i, posData, star, para)
                    table.insert(self.listSkillCell, ltSkillCard)
                    ltSkillCard:SetCallBack(function(data2Logic)
                        if self.callBack then
                            self.callBack(data2Logic)
                        end
                    end)
                    KTool.SetActive(ltSkillCard.controller.gameObject, true)
                end
            end
        end
    end
end

function UIBattlingDiscoverCardRoleCell:SetCallBack(cb)
    self.callBack = cb
end

